const data = $input.first().json || {};
const plugins = Array.isArray(data.plugins) ? data.plugins : [];
return plugins
  .map((p) => {
    const r = p.ratings || {};
    const oneStar = Number(r["1"] || 0);
    const twoStar = Number(r["2"] || 0);
    const unresolved = Math.max(0, Number(p.support_threads || 0) - Number(p.support_threads_resolved || 0));
    const starsOutOf5 = p.rating ? Number((Number(p.rating) / 20).toFixed(2)) : null;
    return {
      json: {
        name: p.name,
        slug: p.slug,
        version: p.version,
        testedUpToWp: p.tested,
        activeInstalls: Number(p.active_installs || 0),
        starsOutOf5,
        oneStarCount: oneStar,
        twoStarCount: twoStar,
        oneTwoStarTotal: oneStar + twoStar,
        unresolvedSupportThreads: unresolved,
        homepage: p.homepage || null,
        pluginUrl: `https://wordpress.org/plugins/${p.slug}/`,
      },
    };
  })
  .filter((item) => item.json.activeInstalls >= 500 && (item.json.oneTwoStarTotal > 0 || item.json.unresolvedSupportThreads > 0))
  .sort((a, b) => (b.json.oneTwoStarTotal + b.json.unresolvedSupportThreads) - (a.json.oneTwoStarTotal + a.json.unresolvedSupportThreads));
